//go:build embedweb

package webui

import (
	"embed"
	"fmt"
	"io/fs"
	"net/http"
)

const Enabled = true

// dist is generated by make build-embed; it must never contain configuration or uploads.
//
//go:embed dist
var content embed.FS

// Wrap serves the embedded release UI and preserves the /api proxy contract.
func Wrap(api http.Handler, routerPrefix string) (http.Handler, error) {
	if routerPrefix != "" {
		return nil, fmt.Errorf("embedweb requires system.router-prefix to be empty; /api is stripped at the HTTP entry point")
	}
	assets, err := fs.Sub(content, "dist")
	if err != nil {
		return nil, err
	}
	return newHandler(api, assets)
}
